class StatementExport
  FORMATTERS = { csv: "StatementExport::CsvFormatter" }.freeze

  def initialize(statement, format: :csv)
    @statement = statement
    @formatter = FORMATTERS.fetch(format).constantize.new
  end

  def render
    @formatter.render(@statement.purchases.map { |purchase| [purchase.posted_on, purchase.merchant, purchase.amount.to_s("F")] })
  end

  class CsvFormatter
    def render(rows)
      CSV.generate { |csv| ([%w[date merchant amount]] + rows).each { |row| csv << row } }
    end
  end
end
